 private void openPack(EngineService.Download d){
  try{
   Uri source=Uri.parse(d.uri);
   try(android.os.ParcelFileDescriptor check=getContentResolver().openFileDescriptor(source,"r")){if(check==null)throw new java.io.FileNotFoundException();}
   Uri pack=PackProvider.share(this,d.uri,d.name);
   Intent intent=new Intent(Intent.ACTION_VIEW).setPackage("com.mojang.minecraftpe");
   intent.setDataAndType(pack,PackProvider.mime(d.name));
   intent.addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);
   intent.setClipData(ClipData.newRawUri(d.name,pack));
   android.content.pm.ResolveInfo handler=getPackageManager().resolveActivity(intent,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);
   if(handler==null){intent.setDataAndType(pack,"application/zip");handler=getPackageManager().resolveActivity(intent,android.content.pm.PackageManager.MATCH_DEFAULT_ONLY);}
   if(handler!=null){intent.setComponent(new ComponentName(handler.activityInfo.packageName,handler.activityInfo.name));}
   else{
    // Some Minecraft versions omit matching content-URI filters. Deliver the
    // VIEW intent and file to the installed game's actual exported entry point.
    Intent launch=getPackageManager().getLaunchIntentForPackage("com.mojang.minecraftpe");
    if(launch==null)throw new ActivityNotFoundException();
    intent.setComponent(launch.getComponent());intent.setDataAndType(pack,PackProvider.mime(d.name));
   }
   startActivity(intent);
  }catch(ActivityNotFoundException e){new AlertDialog.Builder(this).setMessage("ไม่พบ Minecraft ที่เปิดใช้งานอยู่ กรุณาติดตั้งหรือเปิดใช้งาน Minecraft ในโปรไฟล์เดียวกับ Rin23").setPositiveButton("ตกลง",null).show();}
  catch(Exception e){new AlertDialog.Builder(this).setMessage("ส่งไฟล์เข้า Minecraft ไม่สำเร็จ ไฟล์อาจถูกย้ายหรือลบ หรือเกมไม่อนุญาตให้นำเข้า\n\n"+e.getClass().getSimpleName()).setPositiveButton("ตกลง",null).show();}
 }
